-- GENERATED by scripts/db_export_schema.py from the live database. Do not hand-edit.
CREATE OR REPLACE FUNCTION digest.content_stats(p_phone text, p_metric text DEFAULT 'top_authors'::text, p_terms text[] DEFAULT '{}'::text[], p_sources text[] DEFAULT NULL::text[], p_since date DEFAULT NULL::date, p_limit integer DEFAULT 10)
 RETURNS TABLE(label text, value numeric, detail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'digest', 'pg_temp'
AS $function$
declare
  v_chats text[]; v_atid text; v_n int; v_in_fb boolean; v_src text[];
begin
  select case when digest.resolve_asker(p_phone) is not null then 1 else 0 end into v_n;
  if v_n < 1 then return; end if;
  select coalesce(m.channels_present, '{}'), m.at_member_id into v_chats, v_atid
    from digest.member_identity m where m.at_member_id = digest.resolve_asker(p_phone) and digest.is_active_member_status(m.membership_status);
  v_in_fb := v_atid is not null and exists (select 1 from digest.fb_member_map f where f.at_member_id = v_atid);
  v_src := case when coalesce(cardinality(p_sources), 0) = 0 then null else p_sources end;

  return query
  with visible as (
    select ci.*, coalesce(ci.meta->>'author_name', mm.full_name, mm.name) as who
    from digest.content_items ci
    left join digest.members mm on mm.airtable_id = ci.meta->>'sender_member'
    where ci.sensitivity <> 'never_surface' and ci.sensitivity <> 'restricted'
      and (
        (ci.access_rule->>'type' = 'public')
        or (ci.access_rule->>'type' = 'chat_member' and ci.access_rule->>'chat' = any(v_chats))
        or (ci.access_rule->>'type' = 'owner' and v_atid is not null and ci.access_rule->>'member' = v_atid)
        or (ci.access_rule->>'type' = 'fb_group' and v_in_fb)
      )
      and (v_src is null or ci.source = any(v_src))
      and (p_since is null or (ci.occurred_at at time zone 'utc')::date >= p_since)
      and (
        coalesce(cardinality(p_terms), 0) = 0
        or exists (select 1 from unnest(p_terms) t
                   where ci.body ilike '%' || digest.content_like_escape(t) || '%'
                      or ci.tl_dr ilike '%' || digest.content_like_escape(t) || '%'
                      or ci.search_extra ilike '%' || digest.content_like_escape(t) || '%'))
  )
  select * from (
    select v.who::text as label, count(*)::numeric as value,
           (count(*) filter (where v.source = 'fb_post'))::text || ' posts / ' ||
           (count(*) filter (where v.source = 'fb_comment'))::text || ' comments / ' ||
           (count(*) filter (where v.source = 'wa_message'))::text || ' chat messages' as detail
    from visible v
    where p_metric in ('top_authors', 'top_authors_topic')
      and v.who is not null and v.who <> '' and v.who not ilike 'anonymous%'
      and v.source in ('fb_post', 'fb_comment', 'wa_message')
    group by v.who
    order by 2 desc
    limit greatest(coalesce(p_limit, 10), 1)
  ) a
  union all
  select * from (
    select 'total matching items'::text, count(*)::numeric,
           'posts: ' || (count(*) filter (where source = 'fb_post'))::text ||
           ' · comments: ' || (count(*) filter (where source = 'fb_comment'))::text ||
           ' · chat: ' || (count(*) filter (where source = 'wa_message'))::text ||
           ' · people: ' || count(distinct who)::text
    from visible where p_metric = 'count'
    having count(*) > 0
  ) b
  union all
  select * from (
    select to_char(occurred_at, 'YYYY-MM')::text, count(*)::numeric, ''::text
    from visible where p_metric = 'by_month'
    group by 1 order by 1 desc limit 12
  ) c;
end $function$
